// func execAVX512Asm(p *Program) int
// Requires: AVX, AVX512BW, AVX512F, AVX512VBMI, AVX512VBMI2, AVX512VL, BMI2, CMOV, POPCNT
TEXT ·execAVX512Asm(SB), NOSPLIT, $0-16
	MOVQ    p+0(FP), DI
	MOVQ    (DI), BX
	MOVQ    8(DI), R8
	SHLQ    $0x05, R8
	ADDQ    BX, R8
	MOVQ    48(DI), R13
	XORL    AX, AX
	MOVQ    56(DI), R10
	SUBQ    $0x00000080, R10
	CMOVQLT AX, R10
	JMP     next

advance:
	ADDQ $0x20, BX

next:
	CMPQ BX, R8
	JAE  ok

	// Output: Out+K must fit Dst, or the arena less its slack.
	MOVBLZX 1(BX), AX
	MOVL    8(BX), CX
	MOVL    20(BX), DX
	MOVQ    R13, R14
	MOVQ    R10, R9
	TESTB   $0x01, AL
	CMOVQNE 72(DI), R14
	CMOVQNE 80(DI), R9
	LEAQ    (DX)(CX*1), R11
	CMPQ    R11, R9
	JA      fail
	ADDQ    R14, DX

	// Source: In; R9 = its length, R14 = Bm.
	MOVQ    24(DI), SI
	MOVQ    32(DI), R9
	MOVL    16(BX), R14
	MOVBLZX (BX), AX
	CMPL    AX, $0x00
	JE      vv
	CMPL    AX, $0x01
	JE      cv
	CMPL    AX, $0x02
	JE      cc
	CMPL    AX, $0x03
	JE      v512
	CMPL    AX, $0x04
	JE      v128
	CMPL    AX, $0x05
	JE      nat
	CMPL    AX, $0x06
	JE      copy
	JMP     fail

vv:
	// out[j] = bit j ? R[r++] : L[l++] (upstream merge_vec_vec_avx512)
	LEAQ    7(CX), AX
	SHRQ    $0x03, AX
	ADDQ    R14, AX
	CMPQ    AX, R9
	JA      fail
	ADDQ    R14, SI
	MOVL    24(BX), R11
	MOVL    28(BX), R12
	LEAQ    (R11)(CX*1), AX
	CMPQ    AX, R10
	JA      fail
	LEAQ    (R12)(CX*1), AX
	CMPQ    AX, R10
	JA      fail
	MOVQ    CX, R9
	SHRQ    $0x07, R9
	JZ      vv_one
	PCALIGN $0x40

vv_loop:
	MOVQ      (SI), AX
	KMOVQ     AX, K1
	KNOTQ     K1, K2
	VPXORD    Z0, Z0, Z0
	VMOVDQU64 (R13)(R11*1), Z1
	VPEXPANDB Z1, K2, Z0
	VMOVDQU64 (R13)(R12*1), Z2
	VPEXPANDB Z2, K1, Z0
	VMOVDQU64 Z0, (DX)
	POPCNTQ   AX, AX
	MOVL      $0x00000040, R14
	SUBQ      AX, R14
	ADDQ      AX, R12
	ADDQ      R14, R11
	MOVQ      8(SI), AX
	KMOVQ     AX, K4
	KNOTQ     K4, K5
	VPXORD    Z3, Z3, Z3
	VMOVDQU64 (R13)(R11*1), Z1
	VPEXPANDB Z1, K5, Z3
	VMOVDQU64 (R13)(R12*1), Z2
	VPEXPANDB Z2, K4, Z3
	VMOVDQU64 Z3, 64(DX)
	POPCNTQ   AX, AX
	MOVL      $0x00000040, R14
	SUBQ      AX, R14
	ADDQ      AX, R12
	ADDQ      R14, R11
	ADDQ      $0x10, SI
	SUBQ      $-128, DX
	DECQ      R9
	JNZ       vv_loop

vv_one:
	BTL       $0x06, CX
	JNC       vv_tail
	MOVQ      (SI), AX
	KMOVQ     AX, K1
	KNOTQ     K1, K2
	VPXORD    Z0, Z0, Z0
	VMOVDQU64 (R13)(R11*1), Z1
	VPEXPANDB Z1, K2, Z0
	VMOVDQU64 (R13)(R12*1), Z2
	VPEXPANDB Z2, K1, Z0
	VMOVDQU64 Z0, (DX)
	POPCNTQ   AX, AX
	MOVL      $0x00000040, R14
	SUBQ      AX, R14
	ADDQ      AX, R12
	ADDQ      R14, R11
	ADDQ      $0x08, SI
	ADDQ      $0x40, DX

vv_tail:
	ANDL       $0x3f, CX
	JZ         vv_check
	LEAL       7(CX), AX
	SHRL       $0x03, AX
	MOVQ       $-1, R9
	BZHIQ      AX, R9, AX
	KMOVQ      AX, K3
	VMOVDQU8.Z (SI), K3, X1
	VMOVQ      X1, AX
	BZHIQ      CX, R9, R9
	ANDQ       R9, AX
	KMOVQ      AX, K1
	KMOVQ      R9, K3
	POPCNTQ    AX, AX
	KANDNQ     K3, K1, K2
	VPXORD     Z0, Z0, Z0
	VMOVDQU64  (R13)(R11*1), Z1
	VPEXPANDB  Z1, K2, Z0
	VMOVDQU64  (R13)(R12*1), Z2
	VPEXPANDB  Z2, K1, Z0
	VMOVDQU8   Z0, K3, (DX)
	ADDQ       AX, R12

vv_check:
	MOVL 28(BX), AX
	SUBQ AX, R12
	MOVL 12(BX), AX
	CMPQ R12, AX
	JNE  fail
	JMP  advance

cv:
	// out[j] = bit j ? R[r++] : P (upstream merge_cst_vec_avx512)
	LEAQ         7(CX), AX
	SHRQ         $0x03, AX
	ADDQ         R14, AX
	CMPQ         AX, R9
	JA           fail
	ADDQ         R14, SI
	MOVL         28(BX), R12
	LEAQ         (R12)(CX*1), AX
	CMPQ         AX, R10
	JA           fail
	MOVBLZX      3(BX), AX
	VPBROADCASTB AX, Z16
	MOVQ         CX, R9
	SHRQ         $0x07, R9
	JZ           cv_one
	PCALIGN      $0x40

cv_loop:
	MOVQ      (SI), AX
	KMOVQ     AX, K1
	VMOVDQA64 Z16, Z0
	VMOVDQU64 (R13)(R12*1), Z2
	VPEXPANDB Z2, K1, Z0
	VMOVDQU64 Z0, (DX)
	POPCNTQ   AX, AX
	ADDQ      AX, R12
	MOVQ      8(SI), AX
	KMOVQ     AX, K4
	VMOVDQA64 Z16, Z3
	VMOVDQU64 (R13)(R12*1), Z2
	VPEXPANDB Z2, K4, Z3
	VMOVDQU64 Z3, 64(DX)
	POPCNTQ   AX, AX
	ADDQ      AX, R12
	ADDQ      $0x10, SI
	SUBQ      $-128, DX
	DECQ      R9
	JNZ       cv_loop

cv_one:
	BTL       $0x06, CX
	JNC       cv_tail
	MOVQ      (SI), AX
	KMOVQ     AX, K1
	VMOVDQA64 Z16, Z0
	VMOVDQU64 (R13)(R12*1), Z2
	VPEXPANDB Z2, K1, Z0
	VMOVDQU64 Z0, (DX)
	POPCNTQ   AX, AX
	ADDQ      AX, R12
	ADDQ      $0x08, SI
	ADDQ      $0x40, DX

cv_tail:
	ANDL       $0x3f, CX
	JZ         cv_check
	LEAL       7(CX), AX
	SHRL       $0x03, AX
	MOVQ       $-1, R9
	BZHIQ      AX, R9, AX
	KMOVQ      AX, K3
	VMOVDQU8.Z (SI), K3, X1
	VMOVQ      X1, AX
	BZHIQ      CX, R9, R9
	ANDQ       R9, AX
	KMOVQ      AX, K1
	KMOVQ      R9, K3
	POPCNTQ    AX, AX
	VMOVDQA64  Z16, Z0
	VMOVDQU64  (R13)(R12*1), Z2
	VPEXPANDB  Z2, K1, Z0
	VMOVDQU8   Z0, K3, (DX)
	ADDQ       AX, R12

cv_check:
	MOVL 28(BX), AX
	SUBQ AX, R12
	MOVL 12(BX), AX
	CMPQ R12, AX
	JNE  fail
	JMP  advance

cc:
	// out[j] = bit j ? Q : P (upstream merge_cst_cst_avx512)
	LEAQ         7(CX), AX
	SHRQ         $0x03, AX
	ADDQ         R14, AX
	CMPQ         AX, R9
	JA           fail
	ADDQ         R14, SI
	MOVBLZX      3(BX), AX
	VPBROADCASTB AX, Z16
	MOVBLZX      4(BX), AX
	VPBROADCASTB AX, Z17
	MOVQ         CX, R9
	SHRQ         $0x06, R9
	JZ           cc_tail
	PCALIGN      $0x40

cc_loop:
