	VZEROUPPER
	MOVQ $-1, AX
	MOVQ AX, ret+8(FP)
	RET

// func execAVX2Asm(p *Program) int
// Requires: AVX, AVX2, BMI2, CMOV, POPCNT
TEXT ·execAVX2Asm(SB), NOSPLIT, $16-16
	MOVQ    p+0(FP), DI
	LEAQ    avx2DecTab<>+0(SB), R8
	MOVQ    (DI), BX
	MOVQ    8(DI), AX
	SHLQ    $0x05, AX
	ADDQ    BX, AX
	MOVQ    AX, (SP)
	MOVQ    48(DI), R13
	XORL    R9, R9
	MOVQ    56(DI), AX
	SUBQ    $0x00000080, AX
	CMOVQLT R9, AX
	MOVQ    AX, 8(SP)
	JMP     next

advance:
	ADDQ $0x20, BX

next:
	CMPQ BX, (SP)
	JAE  ok

	// Output: Out+K must fit Dst, or the arena less its slack.
	MOVBLZX 1(BX), AX
	MOVL    8(BX), CX
	MOVL    20(BX), DX
	MOVQ    R13, R14
	MOVQ    8(SP), R9
	TESTB   $0x01, AL
	CMOVQNE 72(DI), R14
	CMOVQNE 80(DI), R9
	LEAQ    (DX)(CX*1), R11
	CMPQ    R11, R9
	JA      fail
	ADDQ    R14, DX

	// Source: In; R9 = its length, R14 = Bm.
	MOVQ    24(DI), SI
	MOVQ    32(DI), R9
	MOVL    16(BX), R14
	MOVBLZX (BX), AX
	CMPL    AX, $0x00
	JE      vv
	CMPL    AX, $0x01
	JE      cv
	CMPL    AX, $0x02
	JE      cc
	CMPL    AX, $0x03
	JE      v512
	CMPL    AX, $0x04
	JE      v128
	CMPL    AX, $0x05
	JE      nat
	CMPL    AX, $0x06
	JE      copy
	JMP     fail

