// func gatherAsm(ranks *byte, src *byte, n int, s2r *[256]byte) uint8
// Requires: AVX, AVX2, AVX512BW, AVX512F, AVX512VBMI, AVX512VL, BMI2
TEXT ·gatherAsm(SB), NOSPLIT, $0-33
	MOVQ      ranks+0(FP), AX
	MOVQ      src+8(FP), CX
	MOVQ      n+16(FP), DX
	MOVQ      s2r+24(FP), BX
	VMOVDQU64 (BX), Z0
	VMOVDQU64 64(BX), Z1
	VMOVDQU64 128(BX), Z2
	VMOVDQU64 192(BX), Z3
	VPXORQ    Z4, Z4, Z4
	XORQ      BX, BX
	SUBQ      $0x80, DX
	JL        gather_one
	PCALIGN   $0x40

gather_loop:
	VMOVDQU64 (CX)(BX*1), Z5
	VMOVDQU64 64(CX)(BX*1), Z7
	VPMOVB2M  Z5, K1
	VMOVDQA64 Z5, Z6
	VPERMI2B  Z1, Z0, Z6
	VPERMI2B  Z3, Z2, Z5
	VPBLENDMB Z5, Z6, K1, Z6
	VPMOVB2M  Z7, K1
	VMOVDQA64 Z7, Z5
	VPERMI2B  Z1, Z0, Z5
	VPERMI2B  Z3, Z2, Z7
	VPBLENDMB Z7, Z5, K1, Z5
	VMOVDQU64 Z6, (AX)(BX*1)
	VMOVDQU64 Z5, 64(AX)(BX*1)
	VPMAXUB   Z6, Z5, Z6
	VPMAXUB   Z6, Z4, Z4
	ADDQ      $0x80, BX
	CMPQ      BX, DX
	JLE       gather_loop

gather_one:
	ADDQ      $0x40, DX
	CMPQ      BX, DX
	JG        gather_tail
	VMOVDQU64 (CX)(BX*1), Z5
	VPMOVB2M  Z5, K1
	VMOVDQA64 Z5, Z6
	VPERMI2B  Z1, Z0, Z6
	VPERMI2B  Z3, Z2, Z5
	VPBLENDMB Z5, Z6, K1, Z6
	VPMAXUB   Z6, Z4, Z4
	VMOVDQU64 Z6, (AX)(BX*1)
	ADDQ      $0x40, BX

gather_tail:
	ADDQ       $0x40, DX
	SUBQ       BX, DX
	JZ         gather_done
	MOVQ       $-1, SI
	BZHIQ      DX, SI, SI
	KMOVQ      SI, K1
	VMOVDQU8.Z (CX)(BX*1), K1, Z5
	VPMOVB2M   Z5, K2
	VMOVDQA64  Z5, Z6
	VPERMI2B   Z1, Z0, Z6
	VPERMI2B   Z3, Z2, Z5
	VPBLENDMB  Z5, Z6, K2, Z6
	VPMAXUB    Z6, Z4, K1, Z4
	VMOVDQU8   Z6, K1, (AX)(BX*1)

gather_done:
	VEXTRACTI64X4 $0x01, Z4, Y0
	VPMAXUB       Y0, Y4, Y0
	VEXTRACTI32X4 $0x01, Y0, X1
	VPMAXUB       X1, X0, X1
	VPSRLDQ       $0x08, X1, X0
	VPMAXUB       X0, X1, X1
	VPSRLDQ       $0x04, X1, X0
	VPMAXUB       X0, X1, X1
	VPSRLDQ       $0x02, X1, X0
	VPMAXUB       X0, X1, X1
	VPSRLDQ       $0x01, X1, X0
	VPMAXUB       X0, X1, X1
	VMOVD         X1, AX
	MOVB          AL, ret+32(FP)
	VZEROUPPER
	RET

// func partFullAsm(ranks *byte, right *byte, bm *byte, n int, thr uint8) int
// Requires: AVX, AVX512BW, AVX512F, AVX512VBMI2, BMI2, POPCNT
TEXT ·partFullAsm(SB), NOSPLIT, $0-48
	MOVQ         ranks+0(FP), AX
	MOVQ         right+8(FP), CX
	MOVQ         AX, DX
	MOVQ         bm+16(FP), BX
	MOVQ         n+24(FP), SI
	MOVBLZX      thr+32(FP), DI
	VPBROADCASTB DI, Z0
	XORQ         DI, DI
	XORQ         R8, R8
	SUBQ         $0x40, SI
	JB           partFullAsm_tail
	PCALIGN      $0x40

partFullAsm_loop:
	VMOVDQU64   (AX), Z1
	VPCMPUB     $0x06, Z0, Z1, K1
	KMOVQ       K1, (BX)
	KMOVQ       K1, R9
	POPCNTQ     R9, R9
	VMOVDQA64   Z1, Z2
	VPCOMPRESSB Z1, K1, Z2
	VMOVDQU64   Z2, (CX)(DI*1)
	KNOTQ       K1, K1
	VPCOMPRESSB Z1, K1, Z1
	VMOVDQU64   Z1, (DX)(R8*1)
	ADDQ        $0x40, R8
	SUBQ        R9, R8
	ADDQ        R9, DI
	ADDQ        $0x40, AX
	ADDQ        $0x08, BX
	SUBQ        $0x40, SI
	JAE         partFullAsm_loop

partFullAsm_tail:
	ADDQ        $0x40, SI
	JZ          partFullAsm_done
	MOVQ        $-1, R9
	BZHIQ       SI, R9, R9
	KMOVQ       R9, K1
	VMOVDQU8.Z  (AX), K1, Z1
	VPCMPUB     $0x06, Z0, Z1, K1, K2
	KMOVQ       K2, (BX)
	KMOVQ       K2, AX
	POPCNTQ     AX, AX
	VMOVDQA64   Z1, Z0
	VPCOMPRESSB Z1, K2, Z0
	VMOVDQU64   Z0, (CX)(DI*1)
	KANDNQ      K1, K2, K2
	VPCOMPRESSB Z1, K2, Z1
	VMOVDQU8    Z1, K1, (DX)(R8*1)
	ADDQ        SI, R8
	SUBQ        AX, R8
	ADDQ        AX, DI

partFullAsm_done:
	MOVQ DI, ret+40(FP)
	VZEROUPPER
	RET

// func partRightAsm(ranks *byte, right *byte, bm *byte, n int, thr uint8) int
