	VPCMPUB     $0x06, Z0, Z1, K1
	KMOVQ       K1, (DX)
	KMOVQ       K1, DI
	POPCNTQ     DI, DI
	VPCOMPRESSB Z1, K1, Z1
	VMOVDQU64   Z1, (CX)(SI*1)
	ADDQ        DI, SI
	ADDQ        $0x40, AX
	ADDQ        $0x08, DX
	SUBQ        $0x40, BX
	JAE         partRightAsm_loop

partRightAsm_tail:
	ADDQ        $0x40, BX
	JZ          partRightAsm_done
	MOVQ        $-1, DI
	BZHIQ       BX, DI, DI
	KMOVQ       DI, K1
	VMOVDQU8.Z  (AX), K1, Z1
	VPCMPUB     $0x06, Z0, Z1, K1, K1
	KMOVQ       K1, (DX)
	KMOVQ       K1, AX
