// func packAsm(dst *byte, ranks *byte, n int, n512 int, n128 int, d uint8, base uint8)
// Requires: AVX, AVX512BW, AVX512F, AVX512VBMI, AVX512VL, BMI2
TEXT ·packAsm(SB), NOSPLIT, $0-42
	MOVQ         dst+0(FP), AX
	MOVQ         ranks+8(FP), CX
	MOVQ         n+16(FP), DX
	MOVQ         n512+24(FP), BX
	MOVQ         n128+32(FP), SI
	MOVBQZX      d+40(FP), DI
	MOVBLZX      base+41(FP), R8
	NEGL         R8
	VPBROADCASTB R8, Z0
	SUBQ         BX, DX
	SUBQ         SI, DX
	CMPQ         DI, $0x02
	JEQ          pack_d2
	CMPQ         DI, $0x03
	JEQ          pack_d3
	CMPQ         DI, $0x04
	JEQ          pack_d4
	CMPQ         DI, $0x05
	JEQ          pack_d5
	CMPQ         DI, $0x06
	JEQ          pack_d6
	CMPQ         DI, $0x07
	JEQ          pack_d7
	CMPQ         DI, $0x08
	JEQ          pack_d8
	JMP          pack_done

pack_d2:
	MOVQ         BX, DI
	ORQ          SI, DI
	JZ           pack_d2_vert_end
	VPBROADCASTD packMasks<>+8(SB), Z1
	VPBROADCASTD packMasks<>+16(SB), Z2
	VPBROADCASTD packMasks<>+24(SB), Z3
	SHRQ         $0x09, BX
	JZ           pack_d2_v512_end
	PCALIGN      $0x40

pack_d2_v512:
	VPADDB     (CX), Z0, Z4
	VPADDB     64(CX), Z0, Z5
	VPSLLW     $0x02, Z5, Z5
	VPTERNLOGD $0xf8, Z1, Z5, Z4
	VPADDB     128(CX), Z0, Z5
	VPSLLW     $0x04, Z5, Z5
	VPTERNLOGD $0xf8, Z2, Z5, Z4
	VPADDB     192(CX), Z0, Z5
	VPSLLW     $0x06, Z5, Z5
	VPTERNLOGD $0xf8, Z3, Z5, Z4
	VPADDB     256(CX), Z0, Z5
	VPADDB     320(CX), Z0, Z6
	VPSLLW     $0x02, Z6, Z6
	VPTERNLOGD $0xf8, Z1, Z6, Z5
	VPADDB     384(CX), Z0, Z6
	VPSLLW     $0x04, Z6, Z6
	VPTERNLOGD $0xf8, Z2, Z6, Z5
	VPADDB     448(CX), Z0, Z6
	VPSLLW     $0x06, Z6, Z6
	VPTERNLOGD $0xf8, Z3, Z6, Z5
	VMOVDQU64  Z4, (AX)
	VMOVDQU64  Z5, 64(AX)
	ADDQ       $0x00000200, CX
	ADDQ       $0x00000080, AX
	DECQ       BX
	JNZ        pack_d2_v512

pack_d2_v512_end:
	SHRQ    $0x07, SI
	JZ      pack_d2_v128_end
	PCALIGN $0x40

pack_d2_v128:
	VPADDB     (CX), X0, X4
	VPADDB     16(CX), X0, X5
	VPSLLW     $0x02, X5, X5
	VPTERNLOGD $0xf8, X1, X5, X4
	VPADDB     32(CX), X0, X5
	VPSLLW     $0x04, X5, X5
	VPTERNLOGD $0xf8, X2, X5, X4
	VPADDB     48(CX), X0, X5
	VPSLLW     $0x06, X5, X5
	VPTERNLOGD $0xf8, X3, X5, X4
	VPADDB     64(CX), X0, X5
	VPADDB     80(CX), X0, X6
	VPSLLW     $0x02, X6, X6
	VPTERNLOGD $0xf8, X1, X6, X5
	VPADDB     96(CX), X0, X6
	VPSLLW     $0x04, X6, X6
	VPTERNLOGD $0xf8, X2, X6, X5
	VPADDB     112(CX), X0, X6
