	ADDQ       $0x00000080, CX
	ADDQ       $0x00000020, AX
	DECQ       SI
	JNZ        pack_d2_v128

pack_d2_v128_end:
pack_d2_vert_end:
	TESTQ     DX, DX
	JZ        pack_d2_nat_end
	VMOVDQU64 packShufD2<>+0(SB), Z1
	VMOVDQU64 packShufD2<>+64(SB), Z2
	VMOVDQU64 packShufD2<>+128(SB), Z3
