	VPSLLD     $0x06, Z5, Z5
	VPTERNLOGD $0xfe, Z8, Z7, Z6
	VPORD      Z5, Z6, Z6
	VMOVDQU64  X6, (AX)
	ADDQ       $0x40, CX
