	ADDQ       $0x40, DX
	JZ         pack_d2_nat_end
	MOVQ       $-1, BX
	BZHIQ      DX, BX, BX
	KMOVQ      BX, K1
	VMOVDQU8.Z (CX), K1, Z5
	VPADDB.Z   Z0, Z5, K1, Z5
	VPERMB     Z5, Z1, Z0
	VPERMB     Z5, Z2, Z1
