	VPTERNLOGD $0xfe, Z2, Z1, Z0
	VPORD      Z3, Z0, Z0
	IMUL3Q     $0x02, DX, CX
	ADDQ       $0x07, CX
	SHRQ       $0x03, CX
	MOVQ       $-1, DX
	BZHIQ      CX, DX, DX
	KMOVQ      DX, K1
	VMOVDQU8   Z0, K1, (AX)

pack_d2_nat_end:
