// func gatherAVX2Asm(ranks *byte, src *byte, n int, s2r *[256]byte) uint8
// Requires: AVX, AVX2, CMOV
TEXT ·gatherAVX2Asm(SB), NOSPLIT, $512-33
	MOVQ      ranks+0(FP), R8
	MOVQ      src+8(FP), R9
	MOVQ      n+16(FP), R10
	MOVQ      s2r+24(FP), R11
	VPMOVZXBW (R11), Y0
	VPSLLW    $0x08, Y0, Y0
	VMOVDQU   Y0, (SP)
	VPMOVZXBW 16(R11), Y0
	VPSLLW    $0x08, Y0, Y0
	VMOVDQU   Y0, 32(SP)
	VPMOVZXBW 32(R11), Y0
	VPSLLW    $0x08, Y0, Y0
	VMOVDQU   Y0, 64(SP)
	VPMOVZXBW 48(R11), Y0
	VPSLLW    $0x08, Y0, Y0
	VMOVDQU   Y0, 96(SP)
	VPMOVZXBW 64(R11), Y0
	VPSLLW    $0x08, Y0, Y0
	VMOVDQU   Y0, 128(SP)
	VPMOVZXBW 80(R11), Y0
	VPSLLW    $0x08, Y0, Y0
	VMOVDQU   Y0, 160(SP)
	VPMOVZXBW 96(R11), Y0
	VPSLLW    $0x08, Y0, Y0
	VMOVDQU   Y0, 192(SP)
	VPMOVZXBW 112(R11), Y0
	VPSLLW    $0x08, Y0, Y0
	VMOVDQU   Y0, 224(SP)
	VPMOVZXBW 128(R11), Y0
	VPSLLW    $0x08, Y0, Y0
	VMOVDQU   Y0, 256(SP)
	VPMOVZXBW 144(R11), Y0
	VPSLLW    $0x08, Y0, Y0
	VMOVDQU   Y0, 288(SP)
	VPMOVZXBW 160(R11), Y0
	VPSLLW    $0x08, Y0, Y0
	VMOVDQU   Y0, 320(SP)
	VPMOVZXBW 176(R11), Y0
	VPSLLW    $0x08, Y0, Y0
	VMOVDQU   Y0, 352(SP)
	VPMOVZXBW 192(R11), Y0
	VPSLLW    $0x08, Y0, Y0
	VMOVDQU   Y0, 384(SP)
	VPMOVZXBW 208(R11), Y0
	VPSLLW    $0x08, Y0, Y0
	VMOVDQU   Y0, 416(SP)
	VPMOVZXBW 224(R11), Y0
	VPSLLW    $0x08, Y0, Y0
	VMOVDQU   Y0, 448(SP)
	VPMOVZXBW 240(R11), Y0
	VPSLLW    $0x08, Y0, Y0
	VMOVDQU   Y0, 480(SP)
	XORL      R12, R12
	MOVQ      R10, R13
	SUBQ      $0x10, R13
	JB        gather_tail
	PCALIGN   $0x40

gather_loop:
	MOVQ    (R9)(R12*1), AX
	MOVQ    8(R9)(R12*1), BX
	MOVBLZX AL, CX
	MOVBLZX AH, DX
	MOVBLZX (R11)(CX*1), CX
	ADDW    (SP)(DX*2), CX
	MOVW    CX, (R8)(R12*1)
	SHRQ    $0x10, AX
	MOVBLZX BL, SI
	MOVBLZX BH, DI
	MOVBLZX (R11)(SI*1), SI
	ADDW    (SP)(DI*2), SI
	MOVW    SI, 8(R8)(R12*1)
	SHRQ    $0x10, BX
	MOVBLZX AL, CX
	MOVBLZX AH, DX
	MOVBLZX (R11)(CX*1), CX
	ADDW    (SP)(DX*2), CX
	MOVW    CX, 2(R8)(R12*1)
	SHRQ    $0x10, AX
	MOVBLZX BL, SI
	MOVBLZX BH, DI
	MOVBLZX (R11)(SI*1), SI
	ADDW    (SP)(DI*2), SI
	MOVW    SI, 10(R8)(R12*1)
	SHRQ    $0x10, BX
	MOVBLZX AL, CX
	MOVBLZX AH, DX
	MOVBLZX (R11)(CX*1), CX
	ADDW    (SP)(DX*2), CX
	MOVW    CX, 4(R8)(R12*1)
	SHRQ    $0x10, AX
	MOVBLZX BL, SI
	MOVBLZX BH, DI
	MOVBLZX (R11)(SI*1), SI
	ADDW    (SP)(DI*2), SI
	MOVW    SI, 12(R8)(R12*1)
	SHRQ    $0x10, BX
	MOVBLZX AL, CX
	MOVBLZX AH, DX
	MOVBLZX (R11)(CX*1), CX
	ADDW    (SP)(DX*2), CX
	MOVW    CX, 6(R8)(R12*1)
	MOVBLZX BL, SI
	MOVBLZX BH, DI
	MOVBLZX (R11)(SI*1), SI
	ADDW    (SP)(DI*2), SI
	MOVW    SI, 14(R8)(R12*1)
	ADDQ    $0x10, R12
	CMPQ    R12, R13
	JBE     gather_loop

gather_tail:
	CMPQ R12, R10
	JAE  gather_max

gather_byte:
	MOVBLZX (R9)(R12*1), AX
	MOVBLZX (R11)(AX*1), AX
	MOVB    AL, (R8)(R12*1)
	INCQ    R12
	CMPQ    R12, R10
	JB      gather_byte

gather_max:
	CMPQ  R10, $0x20
	JB    gather_smax
	VPXOR Y0, Y0, Y0
	XORL  R12, R12
	MOVQ  R10, R13
	SUBQ  $0x20, R13

gather_vmax:
	VPMAXUB      (R8)(R12*1), Y0, Y0
	ADDQ         $0x20, R12
	CMPQ         R12, R13
	JBE          gather_vmax
	VPMAXUB      -32(R8)(R10*1), Y0, Y0
	VEXTRACTI128 $0x01, Y0, X1
	VPMAXUB      X1, X0, X0
	VPSRLDQ      $0x08, X0, X1
	VPMAXUB      X1, X0, X0
	VPSRLDQ      $0x04, X0, X1
	VPMAXUB      X1, X0, X0
	VPSRLDQ      $0x02, X0, X1
	VPMAXUB      X1, X0, X0
	VPSRLDQ      $0x01, X0, X1
	VPMAXUB      X1, X0, X0
	VMOVD        X0, AX
	MOVB         AL, ret+32(FP)
	VZEROUPPER
	RET

gather_smax:
	XORL AX, AX
	XORL R12, R12

gather_sloop:
	MOVBLZX (R8)(R12*1), CX
	CMPL    CX, AX
	CMOVLHI CX, AX
	INCQ    R12
	CMPQ    R12, R10
	JB      gather_sloop
	MOVB    AL, ret+32(FP)
