// func histAsm(h *[256]uint32, src *byte, n int, scratch *byte)
// Requires: AVX, AVX512BITALG, AVX512BW, AVX512F, AVX512VBMI, AVX512VBMI2, BMI2, CMOV, GFNI, POPCNT
TEXT ·histAsm(SB), $584-32
	// Port of Harold Aptroot's AVX-512 histogram (https://gitlab.com/-/snippets/3745720); MIT License, see LICENSE-histogram.
	MOVQ  src+8(FP), AX
	MOVQ  n+16(FP), CX
	MOVQ  scratch+24(FP), DX
	ADDQ  $0x3f, DX
	ANDQ  $-64, DX
	MOVQ  AX, BX
	ANDQ  $-64, BX
	ANDQ  $0x3f, AX
	ADDQ  AX, CX
	LEAQ  63(CX), SI
	SHRQ  $0x06, SI
	MOVQ  $-1, DI
	SHLXQ AX, DI, DI
	LEAQ  -1(CX), CX
	ANDQ  $0x3f, CX
	INCQ  CX
	MOVQ  $-1, R9
	BZHIQ CX, R9, R9
	XORQ  R8, R8
	CMPQ  SI, $0x01
	JNE   hist_multi
	ANDQ  R9, DI
	MOVQ  BX, 544(SP)
	MOVQ  DI, 552(SP)
	INCQ  R8
	XORQ  SI, SI
	JMP   hist_setup

hist_multi:
	TESTQ AX, AX
	JZ    hist_nohead
	MOVQ  BX, 544(SP)
	MOVQ  DI, 552(SP)
	INCQ  R8
	ADDQ  $0x40, BX
	DECQ  SI

hist_nohead:
	CMPQ R9, $-1
	JEQ  hist_setup
	DECQ SI
	MOVQ SI, CX
	SHLQ $0x06, CX
	ADDQ BX, CX
	MOVQ R8, AX
	SHLQ $0x04, AX
	MOVQ CX, 544(SP)(AX*1)
	MOVQ R9, 552(SP)(AX*1)
	INCQ R8

hist_setup:
	MOVQ         R8, 576(SP)
	MOVQ         SI, AX
	SHLQ         $0x06, AX
	LEAQ         -64(BX)(AX*1), AX
	MOVQ         $0x2010010204080000, CX
	VPBROADCASTQ CX, Z0
	MOVQ         $0x8040201008040201, CX
	VPBROADCASTQ CX, Z6
	MOVQ         $0x0000000000000001, CX
	VPBROADCASTQ CX, Z5
	MOVL         $0x000000ff, CX
	VPBROADCASTW CX, Z8
	VMOVDQU64    histTranspose<>+0(SB), Z7
	VPTERNLOGD   $0xff, Z1, Z1, Z1
	MOVL         $0xc0c0c0c0, CX
	VPBROADCASTD CX, Z2
	MOVL         $0x40404040, CX
	VPBROADCASTD CX, Z3
	MOVL         $0x80808080, CX
	VPBROADCASTD CX, Z4

hist_round:
	VPXORQ    Z9, Z9, Z9
	VMOVDQU64 Z9, (SP)
	VMOVDQU64 Z9, 64(SP)
	VMOVDQU64 Z9, 128(SP)
	VMOVDQU64 Z9, 192(SP)
	VMOVDQU64 Z9, 256(SP)
	VMOVDQU64 Z9, 320(SP)
	VMOVDQU64 Z9, 384(SP)
	VMOVDQU64 Z9, 448(SP)
	XORQ      CX, CX
	XORQ      R9, R9
	XORQ      R10, R10
	XORQ      R11, R11
	MOVQ      $0x000003ff, DI
	SUBQ      576(SP), DI
	CMPQ      SI, DI
	CMOVQLT   SI, DI
	SUBQ      DI, SI
	XORQ      R8, R8

hist_part:
	CMPQ           R8, 576(SP)
	JAE            hist_partdone
	MOVQ           R8, R12
	SHLQ           $0x04, R12
	MOVQ           544(SP)(R12*1), R13
	KMOVQ          552(SP)(R12*1), K1
	VMOVDQU8.Z     (R13), K1, Z10
	VPANDD         Z2, Z10, Z11
	VPTESTNMB      Z11, Z11, K1, K1
	VPCMPEQB       Z3, Z11, K2
	VPCMPEQB       Z4, Z11, K3
	VPCMPEQB       Z2, Z11, K4
	VGF2P8AFFINEQB $0x00, Z0, Z10, Z10
	VMOVDQA64      Z10, Z11
	VPCOMPRESSB    Z10, K1, Z11
	VMOVDQU64      Z11, (DX)(CX*1)
	KMOVQ          K1, R12
	POPCNTQ        R12, R12
	ADDQ           R12, CX
	VMOVDQA64      Z10, Z11
	VPCOMPRESSB    Z10, K2, Z11
	VMOVDQU64      Z11, 16384(DX)(R9*1)
	KMOVQ          K2, R12
	POPCNTQ        R12, R12
	ADDQ           R12, R9
	VMOVDQA64      Z10, Z11
	VPCOMPRESSB    Z10, K3, Z11
	VMOVDQU64      Z11, 32768(DX)(R10*1)
	KMOVQ          K3, R12
	POPCNTQ        R12, R12
	ADDQ           R12, R10
	VMOVDQA64      Z10, Z11
	VPCOMPRESSB    Z10, K4, Z11
	VMOVDQU64      Z11, 49152(DX)(R11*1)
	KMOVQ          K4, R12
	POPCNTQ        R12, R12
	ADDQ           R12, R11
	INCQ           R8
	JMP            hist_part

hist_partdone:
	MOVQ $+0, 576(SP)

hist_recheck:
	TESTQ   DI, DI
	JZ      hist_roundend
	MOVQ    CX, R8
	CMPQ    R9, R8
	CMOVQHI R9, R8
	CMPQ    R10, R8
	CMOVQHI R10, R8
	CMPQ    R11, R8
	CMOVQHI R11, R8
	CMPQ    R8, $0x00003fc0
	JAE     hist_flushmid
	MOVQ    $0x00003fc0, R12
	SUBQ    R8, R12
	SHRQ    $0x06, R12
	INCQ    R12
	CMPQ    DI, R12
	CMOVQLT DI, R12
	SUBQ    R12, DI
	PCALIGN $0x40

hist_row1:
	VMOVDQA64      (BX), Z10
	VPTESTMB       Z2, Z10, K1
	KORTESTQ       K1, K1
	JNZ            hist_row2
	VGF2P8AFFINEQB $0x00, Z0, Z10, Z10
	VMOVDQU64      Z10, (DX)(CX*1)
	ADDQ           $0x40, CX
	ADDQ           $0x40, BX
	DECQ           R12
	JNZ            hist_row1
	JMP            hist_recheck
	PCALIGN $0x40

hist_row2:
	LEAQ           64(BX), R8
	CMPQ           R8, AX
	CMOVQHI        AX, R8
	VMOVDQA64      (R8), Z11
	VPMOVB2M       Z10, K1
	KORTESTQ       K1, K1
	JNZ            hist_row4
	VPTESTMB       Z3, Z10, K1
	VPTESTNMB      Z3, Z10, K2
	VGF2P8AFFINEQB $0x00, Z0, Z10, Z10
	VMOVDQA64      Z10, Z18
	VPCOMPRESSB    Z10, K2, Z18
	VMOVDQU64      Z18, (DX)(CX*1)
	VPCOMPRESSB    Z10, K1, Z10
	VMOVDQU64      Z10, 16384(DX)(R9*1)
	KMOVQ          K1, R8
	POPCNTQ        R8, R8
	ADDQ           R8, R9
	SUBQ           R8, CX
	ADDQ           $0x40, CX
	VMOVDQA64      Z11, Z10
	ADDQ           $0x40, BX
	DECQ           R12
	JNZ            hist_row2
	JMP            hist_recheck
	PCALIGN $0x40

hist_row4:
	LEAQ           64(BX), R8
	CMPQ           R8, AX
	CMOVQHI        AX, R8
	VMOVDQA64      (R8), Z11
	VPANDD         Z2, Z10, Z18
	VPTESTNMB      Z18, Z18, K1
	VPCMPEQB       Z3, Z18, K2
	VPCMPEQB       Z4, Z18, K3
	VPCMPEQB       Z2, Z18, K4
	VGF2P8AFFINEQB $0x00, Z0, Z10, Z10
	VMOVDQA64      Z10, Z18
	VPCOMPRESSB    Z10, K1, Z18
	VMOVDQU64      Z18, (DX)(CX*1)
	KMOVQ          K1, R8
	POPCNTQ        R8, R8
	ADDQ           R8, CX
	VMOVDQA64      Z10, Z18
	VPCOMPRESSB    Z10, K2, Z18
	VMOVDQU64      Z18, 16384(DX)(R9*1)
	KMOVQ          K2, R8
	POPCNTQ        R8, R8
	ADDQ           R8, R9
	VMOVDQA64      Z10, Z18
	VPCOMPRESSB    Z10, K3, Z18
	VMOVDQU64      Z18, 32768(DX)(R10*1)
	KMOVQ          K3, R8
	POPCNTQ        R8, R8
	ADDQ           R8, R10
	VMOVDQA64      Z10, Z18
	VPCOMPRESSB    Z10, K4, Z18
	VMOVDQU64      Z18, 49152(DX)(R11*1)
	KMOVQ          K4, R8
	POPCNTQ        R8, R8
	ADDQ           R8, R11
	VMOVDQA64      Z11, Z10
	ADDQ           $0x40, BX
	DECQ           R12
	JNZ            hist_row4
	JMP            hist_recheck

hist_roundend:
	MOVQ $0x00000001, R8
	JMP  hist_flush

hist_flushmid:
	MOVQ $0x00003fc0, R8

hist_flush:
	MOVQ CX, 512(SP)
	MOVQ R9, 520(SP)
	MOVQ R10, 528(SP)
	MOVQ R11, 536(SP)
	XORQ R9, R9

hist_flush_bin:
	MOVQ     512(SP)(R9*8), R10
	CMPQ     R10, R8
	JB       hist_flush_next
	MOVQ     R9, R11
	SHLQ     $0x0e, R11
	ADDQ     DX, R11
	LEAQ     (SP), R12
	MOVQ     R9, CX
	SHLQ     $0x07, CX
	ADDQ     CX, R12
	MOVQ     R10, CX
	ANDQ     $0x3f, CX
	JZ       hist_c_nopad
	MOVQ     R10, R13
	ANDQ     $-64, R13
	ADDQ     R11, R13
	MOVQ     $-1, R14
	SHLXQ    CX, R14, R14
	KMOVQ    R14, K1
	VMOVDQU8 Z1, K1, (R13)

hist_c_nopad:
	ADDQ   $0x3f, R10
	SHRQ   $0x06, R10
	VPXORQ Z12, Z12, Z12
	VPXORQ Z13, Z13, Z13
	VPXORQ Z14, Z14, Z14
	VPXORQ Z15, Z15, Z15
	VPXORQ Z16, Z16, Z16

hist_c_outer:
	MOVQ    $0x0000001f, CX
	CMPQ    R10, CX
	CMOVQLT R10, CX
	SUBQ    CX, R10
	VPXORQ  Z17, Z17, Z17
	PCALIGN $0x40

hist_c_inner:
	VPMOVZXBQ      (R11), Z10
	VPSLLVQ        Z10, Z5, Z10
	VPMOVZXBQ      8(R11), Z11
	VPSLLVQ        Z11, Z5, Z11
	VPMOVZXBQ      16(R11), Z18
	VPSLLVQ        Z18, Z5, Z18
	VPMOVZXBQ      24(R11), Z19
	VPSLLVQ        Z19, Z5, Z19
	VPMOVZXBQ      32(R11), Z20
	VPSLLVQ        Z20, Z5, Z20
	VPMOVZXBQ      40(R11), Z21
	VPSLLVQ        Z21, Z5, Z21
	VPMOVZXBQ      48(R11), Z22
	VPSLLVQ        Z22, Z5, Z22
	VPMOVZXBQ      56(R11), Z23
	VPSLLVQ        Z23, Z5, Z23
	ADDQ           $0x40, R11
	VPTERNLOGD     $0x96, Z10, Z11, Z18
	VPTERNLOGD     $0xb2, Z10, Z18, Z11
	VPTERNLOGD     $0x96, Z19, Z20, Z21
	VPTERNLOGD     $0xb2, Z19, Z21, Z20
	VPTERNLOGD     $0x96, Z22, Z23, Z14
	VPTERNLOGD     $0xb2, Z22, Z14, Z23
	VPTERNLOGD     $0x96, Z18, Z21, Z14
	VPTERNLOGD     $0xb2, Z18, Z14, Z21
	VPTERNLOGD     $0x96, Z11, Z20, Z23
	VPTERNLOGD     $0xb2, Z11, Z23, Z20
	VPTERNLOGD     $0x96, Z23, Z21, Z15
	VPTERNLOGD     $0xb2, Z23, Z15, Z21
	VPTERNLOGD     $0x96, Z21, Z20, Z16
	VPTERNLOGD     $0xb2, Z21, Z16, Z20
	VPERMB         Z20, Z7, Z20
	VGF2P8AFFINEQB $0x00, Z20, Z6, Z20
	VPOPCNTB       Z20, Z20
	VPADDB         Z20, Z17, Z17
	DECQ           CX
	JNZ            hist_c_inner
	VPANDQ         Z8, Z17, Z10
	VPADDW         Z10, Z12, Z12
	VPSRLW         $0x08, Z17, Z10
	VPADDW         Z10, Z13, Z13
	TESTQ          R10, R10
	JNZ            hist_c_outer
	VPERMB         Z14, Z7, Z14
	VGF2P8AFFINEQB $0x00, Z14, Z6, Z14
	VPOPCNTB       Z14, Z14
	VPERMB         Z15, Z7, Z15
	VGF2P8AFFINEQB $0x00, Z15, Z6, Z15
	VPOPCNTB       Z15, Z15
	VPERMB         Z16, Z7, Z16
	VGF2P8AFFINEQB $0x00, Z16, Z6, Z16
	VPOPCNTB       Z16, Z16
	VPADDB         Z15, Z14, Z14
	VPADDB         Z15, Z14, Z14
	VPSLLQ         $0x02, Z16, Z16
	VPADDB         Z16, Z14, Z14
	VPSLLW         $0x03, Z12, Z12
	VPSLLW         $0x03, Z13, Z13
	VPANDQ         Z8, Z14, Z10
	VPADDW         Z10, Z12, Z12
	VPSRLW         $0x08, Z14, Z10
	VPADDW         Z10, Z13, Z13
	VPADDW         (R12), Z12, Z12
	VMOVDQU64      Z12, (R12)
	VPADDW         64(R12), Z13, Z13
	VMOVDQU64      Z13, 64(R12)
	MOVQ           $+0, 512(SP)(R9*8)

hist_flush_next:
	INCQ         R9
	CMPQ         R9, $0x04
	JB           hist_flush_bin
	MOVQ         512(SP), CX
	MOVQ         520(SP), R9
	MOVQ         528(SP), R10
	MOVQ         536(SP), R11
	CMPQ         R8, $0x01
	JNE          hist_recheck
	MOVQ         h+0(FP), DI
	MOVL         $0x0000ffff, CX
	VPBROADCASTD CX, Z10
	VMOVDQU64    (SP), Z11
	VPANDD       Z10, Z11, Z18
	VPSRLD       $0x10, Z11, Z11
	VPADDD       (DI), Z18, Z18
	VMOVDQU64    Z18, (DI)
	VPADDD       64(DI), Z11, Z11
	VMOVDQU64    Z11, 64(DI)
	VMOVDQU64    64(SP), Z11
	VPANDD       Z10, Z11, Z18
	VPSRLD       $0x10, Z11, Z11
	VPADDD       128(DI), Z18, Z18
	VMOVDQU64    Z18, 128(DI)
	VPADDD       192(DI), Z11, Z11
	VMOVDQU64    Z11, 192(DI)
	VMOVDQU64    128(SP), Z11
	VPANDD       Z10, Z11, Z18
	VPSRLD       $0x10, Z11, Z11
	VPADDD       256(DI), Z18, Z18
	VMOVDQU64    Z18, 256(DI)
	VPADDD       320(DI), Z11, Z11
	VMOVDQU64    Z11, 320(DI)
	VMOVDQU64    192(SP), Z11
	VPANDD       Z10, Z11, Z18
	VPSRLD       $0x10, Z11, Z11
	VPADDD       384(DI), Z18, Z18
	VMOVDQU64    Z18, 384(DI)
	VPADDD       448(DI), Z11, Z11
	VMOVDQU64    Z11, 448(DI)
	VMOVDQU64    256(SP), Z11
	VPANDD       Z10, Z11, Z18
	VPSRLD       $0x10, Z11, Z11
	VPADDD       512(DI), Z18, Z18
	VMOVDQU64    Z18, 512(DI)
	VPADDD       576(DI), Z11, Z11
	VMOVDQU64    Z11, 576(DI)
	VMOVDQU64    320(SP), Z11
	VPANDD       Z10, Z11, Z18
	VPSRLD       $0x10, Z11, Z11
	VPADDD       640(DI), Z18, Z18
	VMOVDQU64    Z18, 640(DI)
	VPADDD       704(DI), Z11, Z11
	VMOVDQU64    Z11, 704(DI)
	VMOVDQU64    384(SP), Z11
	VPANDD       Z10, Z11, Z18
	VPSRLD       $0x10, Z11, Z11
	VPADDD       768(DI), Z18, Z18
	VMOVDQU64    Z18, 768(DI)
	VPADDD       832(DI), Z11, Z11
	VMOVDQU64    Z11, 832(DI)
	VMOVDQU64    448(SP), Z11
	VPANDD       Z10, Z11, Z10
	VPSRLD       $0x10, Z11, Z11
	VPADDD       896(DI), Z10, Z10
	VMOVDQU64    Z10, 896(DI)
	VPADDD       960(DI), Z11, Z11
	VMOVDQU64    Z11, 960(DI)
	TESTQ        SI, SI
	JNZ          hist_round
	VZEROUPPER
	RET
